 94→// PrepareTranscript waits for Claude Code's async transcript flush to complete.
 95→// Claude writes a hook_progress sentinel entry after flushing all pending writes.
 96→func (c *ClaudeCodeAgent) PrepareTranscript(ctx context.Context, sessionRef string) error {
 97→	waitForTranscriptFlush(ctx, sessionRef, time.Now())
 98→	return nil
 99→}
