195→// --- Transcript flush sentinel ---
196→
197→// stopHookSentinel is the string that appears in Claude Code's hook_progress
198→// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
199→const stopHookSentinel = "hooks claude-code stop"
200→
201→// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
202→// Falls back silently after a timeout.
203→func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
204→	const (
205→		maxWait      = 3 * time.Second
206→		pollInterval = 50 * time.Millisecond
207→		tailBytes    = 4096
208→		maxSkew      = 2 * time.Second
209→	)
210→
211→	logCtx := logging.WithComponent(ctx, "agent.claudecode")
212→
213→	// Fast path: skip the poll loop when the sentinel can't possibly appear.
214→	// - File doesn't exist: nothing to poll.
215→	// - File is stale (unmodified for 2+ min): agent isn't running anymore.
216→	//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
217→	//   without firing stop hook).
218→	const staleThreshold = 2 * time.Minute
219→	info, err := os.Stat(transcriptPath)
220→	if err != nil {
221→		// Most likely the file doesn't exist; other errors (permission, etc.)
222→		// would also prevent polling, so skip the wait either way.
223→		return
224→	}
225→	fileAge := time.Since(info.ModTime())
226→	if fileAge > staleThreshold {
227→		logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
228→			slog.Duration("file_age", fileAge),
229→		)
230→		return
231→	}
232→
233→	deadline := time.Now().Add(maxWait)
234→	for time.Now().Before(deadline) {
235→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
236→			logging.Debug(logCtx, "transcript flush sentinel found",
237→				slog.Duration("wait", time.Since(hookStartTime)),
238→			)
239→			return
240→		}
241→		time.Sleep(pollInterval)
242→	}
243→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
244→		slog.Duration("timeout", maxWait),
245→	)
246→}
247→
248→// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
249→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
250→	f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
251→	if err != nil {
252→		return false
253→	}
254→	defer f.Close()
255→
256→	info, err := f.Stat()
257→	if err != nil {
258→		return false
259→	}
260→	offset := info.Size() - tailBytes
261→	if offset < 0 {
262→		offset = 0
263→	}
264→	buf := make([]byte, info.Size()-offset)
265→	if _, err := f.ReadAt(buf, offset); err != nil {
266→		return false
267→	}
268→
269→	lines := strings.Split(string(buf), "\n")
270→	for _, line := range lines {
271→		line = strings.TrimSpace(line)
272→		if line == "" || !strings.Contains(line, stopHookSentinel) {
273→			continue
274→		}
275→
276→		var entry struct {
277→			Timestamp string `json:"timestamp"`
278→		}
279→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
280→			continue
281→		}
282→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
283→		if err != nil {
284→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
285→			if err != nil {
286→				continue
287→			}
288→		}
289→		// Validate timestamp is within acceptable range:
290→		// - Not too far in the past (before hook started minus skew)
291→		// - Not too far in the future (after hook started plus skew)
292→		lowerBound := hookStartTime.Add(-maxSkew)
293→		upperBound := hookStartTime.Add(maxSkew)
294→		if ts.After(lowerBound) && ts.Before(upperBound) {
295→			return true
296→		}
297→	}
298→	return false
299→}
