 38→// ParseHookEvent translates a Gemini CLI hook into a normalized lifecycle Event.
 39→// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
 40→func (g *GeminiCLIAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 41→	switch hookName {
 42→	case HookNameSessionStart:
 43→		return g.parseSessionStart(stdin)
 44→	case HookNameBeforeAgent:
 45→		return g.parseTurnStart(stdin)
 46→	case HookNameAfterAgent:
 47→		return g.parseTurnEnd(stdin)
 48→	case HookNameSessionEnd:
 49→		return g.parseSessionEnd(stdin)
 50→	case HookNamePreCompress:
 51→		return g.parseCompaction(stdin)
 52→	case HookNameBeforeTool, HookNameAfterTool, HookNameBeforeModel,
 53→		HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
 54→		// Acknowledged hooks with no lifecycle action
 55→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 56→	default:
 57→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 58→	}
