 92→// CalculateTokenUsage computes token usage from the transcript starting at the given message offset.
 93→func (g *GeminiCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
 94→	var transcript struct {
 95→		Messages []geminiMessageWithTokens `json:"messages"`
 96→	}
 97→
 98→	if err := json.Unmarshal(transcriptData, &transcript); err != nil {
 99→		return &agent.TokenUsage{}, fmt.Errorf("failed to parse transcript for token usage: %w", err)
100→	}
101→
102→	usage := &agent.TokenUsage{}
103→
104→	for i, msg := range transcript.Messages {
105→		// Skip messages before startMessageIndex
106→		if i < fromOffset {
107→			continue
108→		}
109→
110→		// Only count tokens from gemini (assistant) messages
111→		if msg.Type != MessageTypeGemini {
112→			continue
113→		}
114→
115→		if msg.Tokens == nil {
116→			continue
117→		}
118→
119→		usage.APICallCount++
120→		usage.InputTokens += msg.Tokens.Input
121→		usage.OutputTokens += msg.Tokens.Output
122→		usage.CacheReadTokens += msg.Tokens.Cached
123→	}
124→
125→	return usage, nil
126→}
