201→// GetLastMessageID returns the ID of the last message in the transcript.
202→// Returns empty string if the transcript is empty or the last message has no ID.
203→func GetLastMessageID(data []byte) (string, error) {
204→	transcript, err := ParseTranscript(data)
205→	if err != nil {
206→		return "", err
207→	}
208→	return GetLastMessageIDFromTranscript(transcript), nil
209→}
210→
211→// GetLastMessageIDFromTranscript returns the ID of the last message in a parsed transcript.
212→// Returns empty string if the transcript is empty or the last message has no ID.
213→func GetLastMessageIDFromTranscript(transcript *GeminiTranscript) string {
214→	if len(transcript.Messages) == 0 {
215→		return ""
216→	}
217→	return transcript.Messages[len(transcript.Messages)-1].ID
218→}
219→
220→// GetLastMessageIDFromFile reads a transcript file and returns the last message's ID.
221→// Returns empty string if the file doesn't exist, is empty, or has no messages with IDs.
222→func GetLastMessageIDFromFile(path string) (string, error) {
223→	if path == "" {
224→		return "", nil
225→	}
226→
227→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
228→	if err != nil {
229→		if os.IsNotExist(err) {
230→			return "", nil
231→		}
232→		return "", fmt.Errorf("failed to read transcript: %w", err)
233→	}
234→
235→	if len(data) == 0 {
236→		return "", nil
237→	}
238→
239→	return GetLastMessageID(data)
240→}
