242→// SliceFromMessage returns a Gemini transcript scoped to messages starting from
243→// startMessageIndex. This is the Gemini equivalent of transcript.SliceFromLine —
244→// for Gemini's single JSON blob, scoping is done by message index rather than line offset.
245→// Returns the original data if startMessageIndex <= 0.
246→// Returns nil, nil if startMessageIndex exceeds the number of messages.
247→func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
248→	if len(data) == 0 || startMessageIndex <= 0 {
249→		return data, nil
250→	}
251→
252→	t, err := ParseTranscript(data)
253→	if err != nil {
254→		return nil, fmt.Errorf("failed to parse transcript for slicing: %w", err)
255→	}
256→
257→	if startMessageIndex >= len(t.Messages) {
258→		return nil, nil
259→	}
260→
261→	scoped := &GeminiTranscript{
262→		Messages: t.Messages[startMessageIndex:],
263→	}
264→
265→	out, err := json.Marshal(scoped)
266→	if err != nil {
267→		return nil, fmt.Errorf("failed to marshal scoped transcript: %w", err)
268→	}
269→	return out, nil
270→}
