  1→package opencode
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→	"os"
  7→	"slices"
  8→	"strings"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/agent"
 11→)
 12→
 13→// Compile-time interface assertions
 14→var (
 15→	_ agent.TranscriptAnalyzer = (*OpenCodeAgent)(nil)
 16→	_ agent.TranscriptPreparer = (*OpenCodeAgent)(nil)
 17→	_ agent.TokenCalculator    = (*OpenCodeAgent)(nil)
 18→)
 19→
 20→// ParseExportSession parses export JSON content into an ExportSession structure.
 21→func ParseExportSession(data []byte) (*ExportSession, error) {
 22→	if len(data) == 0 {
 23→		return nil, nil //nolint:nilnil // nil for empty data is expected
 24→	}
 25→
 26→	var session ExportSession
 27→	if err := json.Unmarshal(data, &session); err != nil {
 28→		return nil, fmt.Errorf("failed to parse export session: %w", err)
 29→	}
 30→
 31→	return &session, nil
 32→}
 33→
 34→// parseExportSessionFromFile reads a file and parses its contents as an ExportSession.
 35→func parseExportSessionFromFile(path string) (*ExportSession, error) {
 36→	data, err := os.ReadFile(path) //nolint:gosec // path from agent hook/session state
 37→	if err != nil {
 38→		return nil, err //nolint:wrapcheck // caller adds context or checks os.IsNotExist
 39→	}
 40→	return ParseExportSession(data)
 41→}
 42→
 43→// SliceFromMessage returns an OpenCode export transcript scoped to messages starting from
 44→// startMessageIndex. This is the OpenCode equivalent of transcript.SliceFromLine —
 45→// for OpenCode's JSON format, scoping is done by message index rather than line offset.
 46→// Returns the original data if startMessageIndex <= 0.
 47→// Returns nil, nil if startMessageIndex exceeds the number of messages.
 48→func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
 49→	if len(data) == 0 || startMessageIndex <= 0 {
 50→		return data, nil
 51→	}
 52→
 53→	session, err := ParseExportSession(data)
 54→	if err != nil {
 55→		return nil, fmt.Errorf("failed to parse export session for slicing: %w", err)
 56→	}
 57→	if session == nil {
 58→		return nil, nil
 59→	}
 60→
 61→	if startMessageIndex >= len(session.Messages) {
 62→		return nil, nil
 63→	}
 64→
 65→	scoped := &ExportSession{
 66→		Info:     session.Info,
 67→		Messages: session.Messages[startMessageIndex:],
 68→	}
 69→
 70→	out, err := json.Marshal(scoped)
 71→	if err != nil {
 72→		return nil, fmt.Errorf("failed to marshal scoped session: %w", err)
 73→	}
 74→	return out, nil
 75→}
 76→
 77→// GetTranscriptPosition returns the number of messages in the transcript.
 78→func (a *OpenCodeAgent) GetTranscriptPosition(path string) (int, error) {
 79→	session, err := parseExportSessionFromFile(path)
 80→	if err != nil {
 81→		if os.IsNotExist(err) {
 82→			return 0, nil
 83→		}
 84→		return 0, err
 85→	}
 86→	if session == nil {
 87→		return 0, nil
 88→	}
 89→	return len(session.Messages), nil
 90→}
 91→
 92→// ExtractModifiedFilesFromOffset extracts files modified by tool calls from the given message offset.
 93→func (a *OpenCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
 94→	session, err := parseExportSessionFromFile(path)
 95→	if err != nil {
 96→		if os.IsNotExist(err) {
 97→			return nil, 0, nil
 98→		}
 99→		return nil, 0, err
100→	}
101→	if session == nil {
102→		return nil, 0, nil
103→	}
104→
105→	seen := make(map[string]bool)
106→	var files []string
107→
108→	for i := startOffset; i < len(session.Messages); i++ {
109→		msg := session.Messages[i]
110→		if msg.Info.Role != roleAssistant {
111→			continue
112→		}
113→		for _, part := range msg.Parts {
114→			if part.Type != "tool" || part.State == nil {
115→				continue
116→			}
117→			if !slices.Contains(FileModificationTools, part.Tool) {
118→				continue
119→			}
120→			for _, filePath := range extractFilePaths(part.State) {
121→				if !seen[filePath] {
122→					seen[filePath] = true
123→					files = append(files, filePath)
124→				}
125→			}
126→		}
127→	}
128→
129→	return files, len(session.Messages), nil
130→}
131→
132→// ExtractModifiedFiles extracts modified file paths from raw export JSON transcript bytes.
133→// This is the bytes-based equivalent of ExtractModifiedFilesFromOffset, used by ReadSession.
134→func ExtractModifiedFiles(data []byte) ([]string, error) {
135→	session, err := ParseExportSession(data)
136→	if err != nil {
137→		return nil, err
138→	}
139→	if session == nil {
140→		return nil, nil
141→	}
142→
143→	seen := make(map[string]bool)
144→	var files []string
145→
146→	for _, msg := range session.Messages {
147→		if msg.Info.Role != roleAssistant {
148→			continue
149→		}
150→		for _, part := range msg.Parts {
151→			if part.Type != "tool" || part.State == nil {
152→				continue
153→			}
154→			if !slices.Contains(FileModificationTools, part.Tool) {
155→				continue
156→			}
157→			for _, filePath := range extractFilePaths(part.State) {
158→				if !seen[filePath] {
159→					seen[filePath] = true
160→					files = append(files, filePath)
161→				}
162→			}
163→		}
164→	}
165→
166→	return files, nil
167→}
168→
169→// extractFilePaths extracts file paths from an OpenCode tool's state.
170→// For standard tools (edit, write), the path is in input.filePath or input.path.
171→// For apply_patch (codex models), the paths are in state.metadata.files[].filePath.
172→func extractFilePaths(state *ToolState) []string {
173→	if state == nil {
174→		return nil
175→	}
176→
177→	// Check metadata.files first (used by apply_patch / codex models).
178→	if state.Metadata != nil {
179→		var paths []string
180→		for _, f := range state.Metadata.Files {
181→			if f.FilePath != "" {
182→				paths = append(paths, f.FilePath)
183→			}
184→		}
185→		if len(paths) > 0 {
186→			return paths
187→		}
188→	}
189→
190→	// Fall back to input keys (used by edit, write).
191→	for _, key := range []string{"filePath", "path"} {
192→		if v, ok := state.Input[key]; ok {
193→			if s, ok := v.(string); ok && s != "" {
194→				return []string{s}
195→			}
196→		}
197→	}
198→	return nil
199→}
200→
201→// ExtractPrompts extracts user prompt strings from the transcript starting at the given offset.
202→func (a *OpenCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
203→	session, err := parseExportSessionFromFile(sessionRef)
204→	if err != nil {
205→		if os.IsNotExist(err) {
206→			return nil, nil
207→		}
208→		return nil, err
209→	}
210→	if session == nil {
211→		return nil, nil
212→	}
213→
214→	var prompts []string
215→	for i := fromOffset; i < len(session.Messages); i++ {
216→		msg := session.Messages[i]
217→		if msg.Info.Role != roleUser {
218→			continue
219→		}
220→		// Extract text from parts
221→		content := ExtractTextFromParts(msg.Parts)
222→		if content != "" {
223→			prompts = append(prompts, content)
224→		}
225→	}
226→
227→	return prompts, nil
228→}
229→
230→// ExtractTextFromParts extracts text content from message parts.
231→func ExtractTextFromParts(parts []Part) string {
232→	var texts []string
233→	for _, part := range parts {
234→		if part.Type == "text" && part.Text != "" {
235→			texts = append(texts, part.Text)
236→		}
237→	}
238→	return strings.Join(texts, "\n")
239→}
240→
241→// ExtractAllUserPrompts extracts all user prompts from raw export JSON transcript bytes.
242→// This is a package-level function used by the condensation path.
243→func ExtractAllUserPrompts(data []byte) ([]string, error) {
244→	session, err := ParseExportSession(data)
245→	if err != nil {
246→		return nil, err
247→	}
248→	if session == nil {
249→		return nil, nil
250→	}
251→
252→	var prompts []string
253→	for _, msg := range session.Messages {
254→		if msg.Info.Role != roleUser {
255→			continue
256→		}
257→		content := ExtractTextFromParts(msg.Parts)
258→		if content != "" {
259→			prompts = append(prompts, content)
260→		}
261→	}
262→	return prompts, nil
263→}
264→
265→// CalculateTokenUsage computes token usage from assistant messages starting at the given offset.
266→func (a *OpenCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
267→	session, err := ParseExportSession(transcriptData)
268→	if err != nil {
269→		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
270→	}
271→	if session == nil {
272→		return nil, nil //nolint:nilnil // nil usage for empty data is expected
273→	}
274→
275→	usage := &agent.TokenUsage{}
276→	for i := fromOffset; i < len(session.Messages); i++ {
277→		msg := session.Messages[i]
278→		if msg.Info.Role != roleAssistant || msg.Info.Tokens == nil {
279→			continue
280→		}
281→		usage.InputTokens += msg.Info.Tokens.Input
282→		usage.OutputTokens += msg.Info.Tokens.Output
283→		usage.CacheReadTokens += msg.Info.Tokens.Cache.Read
284→		usage.CacheCreationTokens += msg.Info.Tokens.Cache.Write
285→		usage.APICallCount++
286→	}
287→
288→	return usage, nil
289→}
