183→func TestExtractFilePaths(t *testing.T) {
184→	t.Parallel()
185→
186→	tests := []struct {
187→		name  string
188→		state *ToolState
189→		want  []string
190→	}{
191→		{
192→			name:  "camelCase filePath from input",
193→			state: &ToolState{Input: map[string]any{"filePath": "/repo/main.go"}},
194→			want:  []string{"/repo/main.go"},
195→		},
196→		{
197→			name:  "path key from input",
198→			state: &ToolState{Input: map[string]any{"path": "/repo/main.go"}},
199→			want:  []string{"/repo/main.go"},
200→		},
201→		{
202→			name:  "filePath takes priority over path in input",
203→			state: &ToolState{Input: map[string]any{"filePath": "/a.go", "path": "/b.go"}},
204→			want:  []string{"/a.go"},
205→		},
206→		{
207→			name:  "empty input",
208→			state: &ToolState{Input: map[string]any{}},
209→			want:  nil,
210→		},
211→		{
212→			name:  "nil state",
213→			state: nil,
214→			want:  nil,
215→		},
216→		{
217→			name: "metadata files (apply_patch / codex)",
218→			state: &ToolState{
219→				Input: map[string]any{"patchText": "*** Begin Patch\n***"},
220→				Metadata: &ToolStateMetadata{
221→					Files: []ToolFileInfo{
222→						{FilePath: "/repo/main.go", RelativePath: "main.go"},
223→					},
224→				},
225→			},
226→			want: []string{"/repo/main.go"},
227→		},
228→		{
229→			name: "metadata files with multiple files",
230→			state: &ToolState{
231→				Input: map[string]any{"patchText": "..."},
232→				Metadata: &ToolStateMetadata{
233→					Files: []ToolFileInfo{
234→						{FilePath: "/repo/a.go"},
235→						{FilePath: "/repo/b.go"},
236→					},
237→				},
238→			},
239→			want: []string{"/repo/a.go", "/repo/b.go"},
240→		},
241→		{
242→			name: "metadata takes priority over input",
243→			state: &ToolState{
244→				Input: map[string]any{"filePath": "/input/file.go"},
245→				Metadata: &ToolStateMetadata{
246→					Files: []ToolFileInfo{
247→						{FilePath: "/meta/file.go"},
248→					},
249→				},
250→			},
251→			want: []string{"/meta/file.go"},
252→		},
253→		{
254→			name: "empty metadata falls back to input",
255→			state: &ToolState{
256→				Input:    map[string]any{"filePath": "/repo/main.go"},
257→				Metadata: &ToolStateMetadata{},
258→			},
259→			want: []string{"/repo/main.go"},
260→		},
261→	}
262→
263→	for _, tt := range tests {
264→		t.Run(tt.name, func(t *testing.T) {
265→			t.Parallel()
266→			got := extractFilePaths(tt.state)
267→			if len(got) != len(tt.want) {
268→				t.Fatalf("extractFilePaths() = %v, want %v", got, tt.want)
269→			}
270→			for i := range got {
271→				if got[i] != tt.want[i] {
272→					t.Errorf("extractFilePaths()[%d] = %q, want %q", i, got[i], tt.want[i])
273→				}
274→			}
275→		})
276→	}
277→}
