262→// resolveTranscriptPath determines the correct file path for an agent's session transcript.
263→// Computes the path dynamically from the current repo location for cross-machine portability.
264→func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
265→	repoRoot, err := paths.WorktreeRoot(ctx)
266→	if err != nil {
267→		return "", fmt.Errorf("failed to get worktree root: %w", err)
268→	}
269→
270→	sessionDir, err := agent.GetSessionDir(repoRoot)
271→	if err != nil {
272→		return "", fmt.Errorf("failed to get agent session directory: %w", err)
273→	}
274→	return agent.ResolveSessionFile(sessionDir, sessionID), nil
275→}
