// ExtractPrompts extracts user prompts from the transcript starting at the given line offset.
func (c *ClaudeCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	lines, err := transcript.ParseFromFileAtLine(sessionRef, fromOffset)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", err)
	}

	var prompts []string
	for i := range lines {
		if lines[i].Type != transcript.TypeUser {
			continue
		}
		content := transcript.ExtractUserContent(lines[i].Message)
		if content != "" {
			prompts = append(prompts, textutil.StripIDEContextTags(content))
		}
	}
	return prompts, nil
}

// PrepareTranscript

// ExtractPrompts extracts user prompts from the transcript starting at the given message offset.
func (g *GeminiCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	t, parseErr := ParseTranscript(data)
	if parseErr != nil {
		return nil, fmt.Errorf("failed to parse transcript: %w", parseErr)
	}

	var prompts []string
	for i := fromOffset; i < len(t.Messages); i++ {
		msg := t.Messages[i]
		if msg.Type == MessageTypeUser && msg.Content != "" {
			prompts = append(prompts, msg.Content)
		}
	}
	return prompts, nil
}

// CalculateTokenUsage

// ExtractLastUserPrompt extracts the last user message from transcript data
func ExtractLastUserPrompt(data []byte) (string, error) {
	transcript, err := ParseTranscript(data)
	if err != nil {
		return "", err
	}

	return ExtractLastUserPromptFromTranscript(transcript), nil
}

// ExtractLastUserPromptFromTranscript extracts the last user prompt from a parsed transcript
func ExtractLastUserPromptFromTranscript(transcript *GeminiTranscript) string {
	for i := len(transcript.Messages) - 1; i >= 0; i-- {
		msg := transcript.Messages[i]
		if msg.Type != MessageTypeUser {
			continue
		}

		// Content is now a string field
		if msg.Content != "" {
			return msg.Content
		}
	}
	return ""
}

// ExtractAllUserPrompts

// ExtractPrompts extracts user prompt strings from the transcript starting at the given offset.
func (a *OpenCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	session, err := parseExportSessionFromFile(sessionRef)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	if session == nil {
		return nil, nil
	}

	var prompts []string
	for i := fromOffset; i < len(session.Messages); i++ {
		msg := session.Messages[i]
		if msg.Info.Role != roleUser {
			continue
		}
		// Extract text from parts
		content := ExtractTextFromParts(msg.Parts)
		if content != "" {
			prompts = append(prompts, content)
		}
	}

	return prompts, nil
}

