 37→// ParseHookEvent translates a Gemini CLI hook into a normalized lifecycle Event.
 38→// Returns nil if the hook has no lifecycle significance (e.g., pass-through hooks).
 39→func (g *GeminiCLIAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
 40→	switch hookName {
 41→	case HookNameSessionStart:
 42→		return g.parseSessionStart(stdin)
 43→	case HookNameBeforeAgent:
 44→		return g.parseTurnStart(stdin)
 45→	case HookNameAfterAgent:
 46→		return g.parseTurnEnd(stdin)
 47→	case HookNameSessionEnd:
 48→		return g.parseSessionEnd(stdin)
 49→	case HookNamePreCompress:
 50→		return g.parseCompaction(stdin)
 51→	case HookNameBeforeTool, HookNameAfterTool, HookNameBeforeModel,
 52→		HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
 53→		// Acknowledged hooks with no lifecycle action
 54→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
 55→	default:
 56→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 57→	}
 58→}
