 69→// CalculateTokenUsage computes token usage from the transcript starting at the given message offset.
 70→func (g *GeminiCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
 71→	var transcript struct {
 72→		Messages []geminiMessageWithTokens `json:"messages"`
 73→	}
 74→
 75→	if err := json.Unmarshal(transcriptData, &transcript); err != nil {
 76→		return &agent.TokenUsage{}, fmt.Errorf("failed to parse transcript for token usage: %w", err)
 77→	}
 78→
 79→	usage := &agent.TokenUsage{}
 80→
 81→	for i, msg := range transcript.Messages {
 82→		// Skip messages before startMessageIndex
 83→		if i < fromOffset {
 84→			continue
 85→		}
 86→
 87→		// Only count tokens from gemini (assistant) messages
 88→		if msg.Type != MessageTypeGemini {
 89→			continue
 90→		}
 91→
 92→		if msg.Tokens == nil {
 93→			continue
 94→		}
 95→
 96→		usage.APICallCount++
 97→		usage.InputTokens += msg.Tokens.Input
 98→		usage.OutputTokens += msg.Tokens.Output
 99→		usage.CacheReadTokens += msg.Tokens.Cached
100→	}
101→
102→	return usage, nil
103→}
